        if capacity <= 0:
            capacity = 1

    customer_ids = [nid for nid in node_info.keys() if nid != depot_id]

    # Distance function
    def dist(a, b):
        if dist_matrix is not None:
            try:
                return dist_matrix[a][b]
            except Exception:
                try:
                    return dist_matrix[int(a)][int(b)]
                except Exception:
                    pass
        na = node_info.get(a, {})
        nb = node_info.get(b, {})
        ax, ay = na.get("x", None), na.get("y", None)
        bx, by = nb.get("x", None), nb.get("y", None)
        if ax is not None and ay is not None and bx is not None and by is not None:
            dx = ax - bx
            dy = ay - by
            return (dx * dx + dy * dy) ** 0.5
        # Fallback deterministic pseudo-distance
        return abs(a - b) + 0.001 * (a + b)

    def route_demand(route):
        s = 0
        for nid in route:
            s += node_info[nid].get("demand", 0)
        return s

    def route_cost(route):
        if not route:
            return 0
        c = dist(depot_id, route[0])
        for i in range(len(route) - 1):
            c += dist(route[i], route[i + 1])
        c += dist(route[-1], depot_id)
        return c

    def insertion_delta(route, pos, cust):
        if not route:
            return dist(depot_id, cust) + dist(cust, depot_id)
        if pos == 0:
            return dist(depot_id, cust) + dist(cust, route[0]) - dist(depot_id, route[0])
        if pos == len(route):
            return dist(route[-1], cust) + dist(cust, depot_id) - dist(route[-1], depot_id)
        return dist(route[pos - 1], cust) + dist(cust, route[pos]) - dist(route[pos - 1], route[pos])

    # Seed order: farthest from depot, then demand descending, then id
    ordered = sorted(customer_ids, key=lambda n: (-dist(depot_id, n), -node_info[n].get("demand", 0), n))
    unassigned = ordered[:]
    routes = []

    # Constructive: grow routes by best feasible insertion
    while unassigned:
        seed = unassigned.pop(0)
        route = [seed]
        load = node_info[seed].get("demand", 0)

        improved = True
        while improved and unassigned:
            improved = False
            best = None  # (delta, cust, pos)
            for cust in unassigned:
                d = node_info[cust].get("demand", 0)
                if load + d > capacity:
                    continue
                for pos in range(len(route) + 1):
                    delta = insertion_delta(route, pos, cust)
                    cand = (delta, cust, pos)
                    if best is None or cand < best:
                        best = cand
            if best is not None:
                _, cust, pos = best
                route.insert(pos, cust)
                load += node_info[cust].get("demand", 0)
                unassigned.remove(cust)
                improved = True

        routes.append(route)

    # Repair: if any route empty, remove
    routes = [r for r in routes if r]

    # Local search: intra-route 2-opt
    def two_opt(route):
        best = route[:]
        best_cost = route_cost(best)
        n = len(best)
        if n < 4:
            return best
        improved = True
        while improved:
            improved = False
            for i in range(n - 2):
                for k in range(i + 2, n):
                    cand = best[:i + 1] + best[i + 1:k + 1][::-1] + best[k + 1:]
                    c = route_cost(cand)
                    if c + 1e-12 < best_cost:
                        best = cand
                        best_cost = c
                        improved = True
                        break
                if improved:
                    break
        return best

    routes = [two_opt(r) for r in routes]

    # Inter-route relocate and swap
    def total_cost(rs):
        s = 0
        for rr in rs:
            s += route_cost(rr)
        return s

    changed = True
    while changed:
        changed = False
        base_cost = total_cost(routes)

        # Relocate
        for i in range(len(routes)):
            if changed:
                break
            for j in range(len(routes)):
                if i == j:
                    continue
                ri = routes[i]
                rj = routes[j]
                if not ri:
                    continue
                load_j = route_demand(rj)
                for pi in range(len(ri)):
                    cust = ri[pi]
                    d = node_info[cust].get("demand", 0)
                    if load_j + d > capacity:
                        continue
                    new_ri = ri[:pi] + ri[pi + 1:]
                    for pj in range(len(rj) + 1):
                        new_rj = rj[:pj] + [cust] + rj[pj:]
                        cand_routes = routes[:]
                        cand_routes[i] = new_ri
                        cand_routes[j] = new_rj
                        cand_routes2 = [r for r in cand_routes if r]
                        cand_routes2 = [two_opt(r) for r in cand_routes2]
                        c = total_cost(cand_routes2)
                        if c + 1e-12 < base_cost:
                            routes = cand_routes2
                            changed = True
                            break
                    if changed:
                        break
                if changed:
                    break

        if changed:
            continue

        # Swap
        for i in range(len(routes)):
            if changed:
                break
            for j in range(i + 1, len(routes)):
                ri = routes[i]
                rj = routes[j]
                li = route_demand(ri)
                lj = route_demand(rj)
                for pi in range(len(ri)):
                    a = ri[pi]
                    da = node_info[a].get("demand", 0)
                    for pj in range(len(rj)):
                        b = rj[pj]
                        db = node_info[b].get("demand", 0)
                        if li - da + db > capacity:
                            continue
                        if lj - db + da > capacity:
                            continue
                        new_ri = ri[:]
                        new_rj = rj[:]
                        new_ri[pi] = b
                        new_rj[pj] = a
